from itertools import product

def hamming_distance(s1, s2):
    """Calculates the Hamming distance between two binary strings."""
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def get_C_L(n, k, L):
    """Computes the set C(L) for a given L, n, and k. Returns a sorted tuple for hashability."""
    C_L_list = []

    # Generate all 2^n binary strings S
    all_strings = [''.join(map(str, p)) for p in product([0, 1], repeat=n)]

    for S in all_strings:
        if hamming_distance(L, S) == k:
            C_L_list.append(S)

    # Sort and return as a tuple
    C_L_list.sort()
    return tuple(C_L_list)

def check_uniqueness(n, k):
    """Checks if C(L) is unique for all L when n and k are fixed."""

    # Generate all 2^n possible L strings
    all_L = [''.join(map(str, p)) for p in product([0, 1], repeat=n)]

    # Dictionary to map the set C(L) (as a tuple) to the list of L strings that produce it.
    sets_C_L = {}

    for L in all_L:
        C_L_tuple = get_C_L(n, k, L)

        if C_L_tuple not in sets_C_L:
            sets_C_L[C_L_tuple] = [L]
        else:
            sets_C_L[C_L_tuple].append(L)

    non_unique_groups = {C_L: L_list for C_L, L_list in sets_C_L.items() if len(L_list) > 1}

    if non_unique_groups:
        print(f"--- RESULTS for n={n}, k={k} ---")
        print(f"Found {len(non_unique_groups)} instance(s) where C(L1) = C(L2) for L1 != L2.")
        # Print a small sample of non-unique groups to confirm calculation integrity, although the main task is just the existence check.
        for C_L, L_list in list(non_unique_groups.items())[:2]:
             print(f"Example non-unique set C(L): {C_L}")
             print(f"Produced by L strings: {L_list}")
    else:
        print(f"--- RESULTS for n={n}, k={k} ---")
        print("C(L) is unique for all L. No instances found where C(L1) = C(L2) for L1 != L2.")

    return non_unique_groups

# Case 1: n=4, k=1
non_unique_k1 = check_uniqueness(4, 1)

# Case 2: n=4, k=2
